package vn.edu.eaut.lab8.model; import jakarta.validation.constraints.*; public class SanPham { private int id; @NotBlank(message="Tên sản phẩm không được để trống") private String ten; @Positive(message="Giá phải > 0") private double gia; @PositiveOrZero(message="Số lượng phải >= 0") private int soLuong; public SanPham(){} public SanPham(int i,String t,double g,int s){id=i;ten=t;gia=g;soLuong=s;} public int getId(){return id;}public void setId(int v){id=v;}public String getTen(){return ten;}public void setTen(String v){ten=v;}public double getGia(){return gia;}public void setGia(double v){gia=v;}public int getSoLuong(){return soLuong;}public void setSoLuong(int v){soLuong=v;} }
